effect.shader:
vec4 sample(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
float rnd(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453); }

vec3 rgb2hsv(vec3 c){
  vec4 k = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
  vec4 p = mix(vec4(c.bg, k.wz), vec4(c.gb, k.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c){
  vec4 k = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
  vec3 p = abs(fract(c.xxx + k.xyz) * 6.0 - k.www);
  return c.z * mix(k.xxx, clamp(p - k.xxx, 0.0, 1.0), c.y);
}

vec3 screenBlend(vec3 a, vec3 b){ return 1.0 - (1.0 - a) * (1.0 - b); }

void main(){
  vec2 uv = acScreenNorm;
  vec2 res = acScreenSize;
  float aspect = res.x / res.y;

  float a = radians(angle) + progress * 6.28318530718 + acTime * speed;
  vec2 center = vec2(0.5, 0.5);
  vec2 pos1 = center + vec2(cos(a), sin(a)) * radius;
  vec2 pos2 = center + vec2(cos(a + 3.14159265359), sin(a + 3.14159265359)) * radius;

  vec2 uvA = uv * vec2(aspect, 1.0);
  vec2 p1A = pos1 * vec2(aspect, 1.0);
  vec2 p2A = pos2 * vec2(aspect, 1.0);

  float d1 = distance(uvA, p1A);
  float d2 = distance(uvA, p2A);

  float s1 = exp(-d1 * falloff1);
  float s2 = exp(-d2 * falloff2);

  vec3 c1 = color1.rgb * s1;
  vec3 c2 = color2.rgb * s2;
  vec3 grad = clamp(c1 + c2, 0.0, 1.0);

  float n = rnd(uv);
  grad += n * noiseAmt;

  vec3 base = sample(uv).rgb;
  vec3 comp;
  int bm = int(blendMode);
  if(bm == 0){
    comp = grad;
  } else if(bm == 1){
    comp = base * grad;
  } else if(bm == 2){
    comp = screenBlend(base, grad);
  } else if(bm == 3){
    comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, base));
  } else if(bm == 4){
    vec3 hb = rgb2hsv(base);
    vec3 hg = rgb2hsv(grad);
    comp = hsv2rgb(vec3(hg.x, hg.y, hb.z));
  } else if(bm == 5 || bm == 13){
    comp = max(base, grad);
  } else if(bm == 6){
    comp = clamp(base / max(1.0 - grad, 1e-6), 0.0, 1.0);
  } else if(bm == 7){
    comp = clamp(1.0 - (1.0 - base) / max(grad, 1e-6), 0.0, 1.0);
  } else if(bm == 8){
    comp = clamp(base + grad, 0.0, 1.0);
  } else if(bm == 9){
    comp = clamp(base + grad - 1.0, 0.0, 1.0);
  } else if(bm == 10){
    comp = clamp(base + 2.0 * grad - 1.0, 0.0, 1.0);
  } else if(bm == 11 || bm == 12){
    comp = min(base, grad);
  } else if(bm == 14){
    comp = clamp((1.0 - 2.0 * grad) * base * base + 2.0 * grad * base, 0.0, 1.0);
  } else if(bm == 15){
    comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, grad));
  } else if(bm == 16){
    comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, grad));
  } else if(bm == 17){
    vec3 hb = rgb2hsv(base);
    vec3 hg = rgb2hsv(grad);
    comp = hsv2rgb(vec3(hg.x, hb.y, hb.z));
  } else if(bm == 18){
    comp = abs(base - grad);
  } else if(bm == 19){
    vec3 hb = rgb2hsv(base);
    vec3 hg = rgb2hsv(grad);
    comp = hsv2rgb(vec3(hb.x, hb.y, hg.z));
  } else if(bm == 20){
    vec3 hb = rgb2hsv(base);
    vec3 hg = rgb2hsv(grad);
    comp = hsv2rgb(vec3(hb.x, hg.y, hb.z));
  } else if(bm == 21){
    vec3 low = clamp(1.0 - (1.0 - base) / max(2.0 * grad, 1e-6), 0.0, 1.0);
    vec3 high = clamp(base / max(2.0 * (1.0 - grad), 1e-6), 0.0, 1.0);
    comp = mix(low, high, step(0.5, grad));
  } else if(bm == 22){
    comp = mix(min(base, 2.0 * grad), max(base, 2.0 * grad - 1.0), step(0.5, grad));
  } else if(bm == 23){
    comp = clamp(base / max(grad, 1e-6), 0.0, 1.0);
  } else if(bm == 24){
    comp = clamp(base - grad, 0.0, 1.0);
  } else {
    comp = screenBlend(base, grad);
  }

  vec3 outc = mix(base, comp, alphab);
  gl_FragColor = vec4(outc, 1.0);
}
